     7	public final class GuardEvaluator {
     8	    private static final Pattern DOCUMENT_ID = Pattern.compile("[A-Za-z0-9][A-Za-z0-9._:-]{0,119}");
     9	    public boolean passes(String id, WorkflowEvaluationContext c) {
    10	        Map<String,Object> f=c.claim().facts().values(); WorkflowEvidence e=c.evidence();
    11	        return switch(id) {
    12	            case "all_required_documents_present" -> documentsValid(f);
    13	            case "assessor_assigned" -> nonblank(f.get("assessorId"));
    14	            case "assessment_report_complete" -> reportComplete(f.get("assessmentReport"));
    15	            case "amount_within_policy_limit" -> amountWithin(f.get("requestedAmount"), c.claim().policyLimit());
    16	            case "rejection_reason_present" -> nonblank(c.command().reason());
    17	            case "information_description_present" -> nonblank(c.command().reason());
    18	            case "new_information_received" -> e.lastInformationRequestedAt()!=null && e.lastInformationReceivedAt()!=null && e.lastInformationReceivedAt().isAfter(e.lastInformationRequestedAt());
    19	            case "payment_request_exists" -> e.paymentRequestExists();
    20	            case "payment_confirmed" -> e.paymentRequestExists() && e.paymentConfirmedAt()!=null && nonblank(e.paymentReference());
    21	            case "appeal_period_expired_or_member_acknowledged" -> e.rejectedAt()!=null &&
    22	                    ((e.memberAcknowledgedRejectionAt()!=null && !e.memberAcknowledgedRejectionAt().isBefore(e.rejectedAt())) ||
    23	                     !c.now().isBefore(e.rejectedAt().plus(c.appealPeriod())));
    24	            default -> false;
    25	        };
    26	    }
    27	    private static boolean nonblank(Object o) { return o instanceof String s && !s.isBlank(); }
    28	    private static boolean amountWithin(Object o, BigDecimal limit) {
    29	        if (!(o instanceof BigDecimal b)) return false;
    30	        return b.signum() >= 0 && b.scale() <= 2 && b.precision() - b.scale() <= 16 && b.compareTo(limit) <= 0;
    31	    }
    32	    private static boolean reportComplete(Object raw) {
    33	        if (!(raw instanceof Map<?, ?> report)) return false;
    34	        return Boolean.TRUE.equals(report.get("complete"));
    35	    }
    36	    private static boolean documentsValid(Map<String,Object> f) {
    37	        Object raw=f.get("documents"); if (!(raw instanceof Map<?,?> docs) || docs.isEmpty()) return false;
    38	        boolean hasRequired = false;
    39	        for (var entry:docs.entrySet()) {
    40	            if (!(entry.getKey() instanceof String id) || !DOCUMENT_ID.matcher(id).matches() || !(entry.getValue() instanceof Map<?,?> d)) return false;
    41	            Object required = d.get("required"), present = d.get("present"), valid = d.get("valid");
    42	            if (!(required instanceof Boolean) || !(present instanceof Boolean) || !(valid instanceof Boolean)) return false;
    43	            if (Boolean.TRUE.equals(required)) {
    44	                hasRequired = true;
    45	                if (!Boolean.TRUE.equals(present) || !Boolean.TRUE.equals(valid)) return false;
    46	            }
    47	        }
    48	        return hasRequired;
    49	    }
    50	}
