    11	    private static final Set<String> SUPPORTED_GUARDS = Set.of(
    12	            "all_required_documents_present", "assessor_assigned", "assessment_report_complete",
    13	            "amount_within_policy_limit", "rejection_reason_present", "information_description_present",
    14	            "new_information_received", "payment_request_exists", "payment_confirmed",
    15	            "appeal_period_expired_or_member_acknowledged");
