    17	            "notify_assessor_team", "record_assessment_start", "notify_member_approval", "create_payment_request",
    18	            "notify_member_rejection", "notify_information_request", "reset_assessment_timer", "trigger_payment_system",
    19	            "notify_member_payment_reference", "archive_claim");
    20	    private static final Set<String> SUPPORTED_ROLES = Set.of("document_clerk", "team_lead", "assessor", "finance", "system");
    21	    private final ObjectMapper mapper = new ObjectMapper(new YAMLFactory())
    22	            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
    23	    public WorkflowDefinition load(InputStream input) {
    24	        try {
    25	            Map<?,?> root = map(mapper.readValue(input, Map.class), "root");
    26	            Map<?,?> w = map(root.get("workflow"), "workflow");
    27	            Set<String> states = uniqueStrings(w.get("states"), "states");
    28	            String initialState = text(w.get("initial-state"));
    29	            if (!states.contains(initialState)) throw bad("Initial state is not declared");
    30	            Map<String,String> guards = new LinkedHashMap<>();
    31	            map(w.get("guard-catalog"),"guard-catalog").forEach((k,v)-> {
    32	                String id = text(k);
    33	                if (!SUPPORTED_GUARDS.contains(id)) throw bad("Unknown guard strategy: " + id);
    34	                guards.put(id, text(map(v,"guard").get("failure-message")));
    35	            });
    36	            Map<String,String> effects = new LinkedHashMap<>();
    37	            map(w.get("effect-catalog"),"effect-catalog").forEach((k,v)-> {
    38	                String id = text(k);
    39	                if (!SUPPORTED_EFFECTS.contains(id)) throw bad("Unknown effect strategy: " + id);
    40	                effects.put(id, text(v));
    41	            });
    42	            List<WorkflowDefinition.Transition> ts=new ArrayList<>(); Set<String> ids=new HashSet<>(); Set<String> edges=new HashSet<>();
    43	            for(Object o:(List<?>)w.get("transitions")) { Map<?,?> t=map(o,"transition"); String id=text(t.get("id")), from=text(t.get("from")), to=text(t.get("to"));
    44	                if(!ids.add(id)||!edges.add(from+"\u0000"+to)) throw bad("Duplicate transition id or edge"); if(!states.contains(from)||!states.contains(to)) throw bad("Dangling transition state");
    45	                List<String> gs=List.copyOf(uniqueStrings(t.get("guards"),"guards")), es=List.copyOf(uniqueStrings(t.get("effects"),"effects")); if(!guards.keySet().containsAll(gs)||!effects.keySet().containsAll(es)) throw bad("Transition references unknown guard or effect");
    46	                Set<String> roles = new LinkedHashSet<>(uniqueStrings(t.get("authorized-roles"), "authorized-roles"));
    47	                if (roles.isEmpty() || !SUPPORTED_ROLES.containsAll(roles)) throw bad("Transition has missing or unknown roles");
    48	                ts.add(new WorkflowDefinition.Transition(id,from,to,roles,gs,es)); }
    49	            Map<?,?> cp=map(w.get("cycle-policy"),"cycle-policy");
    50	            String cycleTransition = text(cp.get("transition-id"));
    51	            String counter = text(cp.get("counter"));
    52	            int max = positiveInteger(cp.get("maximum"), "cycle-policy.maximum");
    53	            String cycleMessage = text(cp.get("error-message"));
    54	            if (ts.stream().noneMatch(t -> t.id().equals(cycleTransition))) throw bad("Cycle policy transition is unknown");
    55	            if (!"informationRequests".equals(counter)) throw bad("Unknown cycle counter: " + counter);
    56	            if (w.containsKey("information-cycle-limit") && positiveInteger(w.get("information-cycle-limit"), "information-cycle-limit") != max)
    57	                throw bad("Information cycle limit must match cycle policy maximum");
    58	            return new WorkflowDefinition(text(w.get("version")),initialState,states,ts,guards,effects,
    59	                    new WorkflowDefinition.CyclePolicy(cycleTransition,counter,max,cycleMessage));
    60	        } catch(IOException|ClassCastException|NullPointerException ex) { throw new IllegalArgumentException("Invalid workflow configuration",ex); }
    61	    }
