     5	public final class WorkflowEngine {
     6	    private final WorkflowDefinition definition; private final GuardEvaluator guards;
     7	    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards) { this.definition=definition; this.guards=guards; }
     8	    public List<WorkflowOption> available(WorkflowEvaluationContext c) {
     9	        return definition.transitions().stream().filter(t -> t.from().equals(c.claim().state())).map(t -> {
    10	            List<String> failures = failures(t, c);
    11	            return new WorkflowOption(t.id(), t.from(), t.to(), t.roles(), failures.isEmpty(), failures, t.effects());
    12	        }).toList();
    13	    }
    14	    public WorkflowDecision evaluate(WorkflowEvaluationContext c) {
    15	        List<WorkflowOption> opts=available(c); WorkflowDefinition.Transition t=definition.transitions().stream().filter(x->x.from().equals(c.claim().state())&&x.to().equals(c.command().targetState())).findFirst().orElse(null);
    16	        if(t==null) return WorkflowDecision.denied("INVALID_EDGE","No transition exists from current state to requested state",opts);
    17	        if(!t.roles().stream().anyMatch(c.actor()::hasRole)) return WorkflowDecision.denied("ROLE_FORBIDDEN","Actor is not authorized for this transition",opts);
    18	        for(String g:t.guards()) if(!guards.passes(g,c)) return WorkflowDecision.denied(g.toUpperCase(java.util.Locale.ROOT),definition.guardMessages().get(g),opts);
    19	        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
    20	        if(t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter())>=cycle.maximum())
    21	            return WorkflowDecision.denied("CYCLE_LIMIT",cycle.errorMessage(),opts);
    22	        return new WorkflowDecision(true,t.id(),t.from(),t.to(),null,null,t.effects(),opts);
    23	    }
    24	    private List<String> failures(WorkflowDefinition.Transition t, WorkflowEvaluationContext c) {
    25	        List<String> failures = new java.util.ArrayList<>();
    26	        if (t.roles().stream().noneMatch(c.actor()::hasRole)) failures.add("ROLE_FORBIDDEN");
    27	        for (String guard : t.guards()) if (!guards.passes(guard, c)) failures.add(guard);
    28	        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
    29	        if (t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter()) >= cycle.maximum()) failures.add("CYCLE_LIMIT");
    30	        return List.copyOf(failures);
    31	    }
    32	}

